<script setup lang="ts">
import TemplateThumbnail from './TemplateThumbnail.vue';
import {computed,ref} from 'vue';import {readTemplateFile} from './templatePlan';import {Plus,Copy,Download,Upload,Layers3} from 'lucide-vue-next';import {download,request} from './model';import type {State,ModuleTemplate} from './model';
const props=defineProps<{state:State}>();const emit=defineEmits<{edit:[template:ModuleTemplate];use:[template:ModuleTemplate];saved:[state:State]}>();const query=ref(''),error=ref(''),deleting=ref(''),busy=ref(false);
const deleteError=ref('');
const list=computed(()=>props.state.templates.filter(t=>[t.name,t.plan.product_model].join(' ').toLowerCase().includes(query.value.toLowerCase())));
function blank(){emit('edit',{id:'',name:'',description:'',updatedAt:'',plan:{name:'微模块',type:'single',rack_count:4,rack_left:4,rack_right:4,u_height:42,layout:[]}})}
async function imported(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>200000)throw new Error('模板文件不能超过200KB');emit('edit',readTemplateFile(JSON.parse(await file.text())))}catch(e){error.value=(e as Error).message}input.value=''}
async function remove(){busy.value=true;deleteError.value='';try{emit('saved',await request<State>('/templates/'+deleting.value,'DELETE',{revision:props.state.revision}));deleting.value=''}catch(e){deleteError.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><section class="template-library"><p class="resource-scope">全局共享布局模板 · 所有项目可使用</p><div class="table-toolbar"><input v-model="query" aria-label="搜索布局模板" placeholder="搜索模板"/><div class="template-library-actions"><label class="button secondary file-button"><Upload :size="15"/>导入模板<input type="file" accept=".json" @change="imported"/></label><button class="primary" @click="blank"><Plus :size="15"/>新建模板</button></div></div><p v-if="error" class="error-banner" role="alert">{{error}}</p><div class="template-grid"><article v-for="t in list" :key="t.id" class="panel template-card"><div class="template-card-heading"><Layers3 :size="24"/><div><h3 :title="t.name">{{t.name}}</h3><p :title="t.plan.product_model">{{t.plan.product_model||'自定义型号'}}</p></div></div><TemplateThumbnail :plan="t.plan"/><p class="template-meta">{{t.plan.type==='double'?'双排':'单排'}} · {{t.plan.type==='double'?(t.plan.rack_left||0)+(t.plan.rack_right||0):t.plan.rack_count}} 柜 · 42U</p><div class="template-card-actions"><button class="primary" :aria-label="`使用模板 ${t.name}`" @click="emit('use',t)">使用模板</button><button class="secondary" :aria-label="`编辑模板 ${t.name}`" @click="emit('edit',JSON.parse(JSON.stringify(t)))">编辑</button><button class="icon-button" :aria-label="`复制模板 ${t.name}`" @click="emit('edit',{...JSON.parse(JSON.stringify(t)),id:'',name:t.name+' 副本'})"><Copy :size="15"/></button><button class="icon-button" :aria-label="`导出模板 ${t.name}`" @click="download('微模块布局模板.json',JSON.stringify({format:'aom-module-template',version:1,template:{name:t.name,description:t.description,plan:t.plan}},null,2))"><Download :size="15"/></button></div><details class="compact-help"><summary>更多</summary><p>{{t.description||'无备注'}}</p><template v-if="deleting===t.id"><p v-if="deleteError" class="error-banner" role="alert">{{deleteError}}</p><span>只删除模板，已建模块保留。</span><button class="danger" :disabled="busy" @click="remove">确认删除模板</button><button class="secondary" :disabled="busy" @click="deleting=''">取消</button></template><button v-else class="text-button danger-text" @click="deleteError='';deleting=t.id">删除模板</button></details></article></div><div v-if="!list.length" class="empty-state"><h3>暂无匹配模板</h3><button class="primary" @click="blank">新建模板</button></div></section></template>
